package com.vidyavedika.ai_practice_service.controller; import com.vidyavedika.ai_practice_service.service.AIService; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/ai") public class AIController {final AIService s; AIController(AIService s){this.s=s;} @PostMapping("/practice") public Map<String,Object> practice(@RequestBody Map<String,Object> r){return s.practice(r);} @PostMapping("/correction") public Map<String,Object> correction(@RequestBody Map<String,String> r){return s.correct(r.getOrDefault("sentence",""));}}